VAR
  Trip_Delay : TON;
END_VAR

// Trip logic: 
// 1. If Motor_Current > 51.9A, start the timer.
// 2. Ignore the trip condition during the first 2 seconds of running (Start_Command edge or Motor_Running start delay).
// 3. Since we cannot use edge detection functions not provided, we use the Motor_Running status as the inhibit condition.
// 4. Assuming 2.0s is sufficient buffer for the 1.5s inrush.

Trip_Delay(IN := (Motor_Current > 51.9) AND Motor_Running, PT := T#2S);

IF Trip_Delay.Q THEN
    Motor_Stop := TRUE;
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Motor_Stop := FALSE;
    Overload_Alarm := FALSE;
END_IF;

